#include <iostream>
#include <string>

int main() {
    std::string s;
    std::getline(std::cin, s);
    s = s[0] + s.substr(1).replace(0, 2, "@");
    std::cout << s[0] + s.substr(1, s.size() - 2).replace(0, 3, ".") + s.back() << std::endl;
    return 0;
}
